(function(E){ const x = E["exam-03"] = E["exam-03"] || {units:{}}; (x.units = x.units || {})["x03-s"] = {"id":"x03-s","patterns":["S1-frame","S1-money","S2-place","S3-culture","TR-short","PARA-discuss"],"title":{"en":"Speaking","tr":"Speaking","fa":"Speaking (صحبت کردن)"},"objective":{"en":"In this lesson you will learn to take the whole Speaking test: answer questions about saving money in two or three sentences, describe a market or street for two minutes so that the listener can picture it, and discuss public spaces with a view, a reason and an example.","tr":"Bu derste Speaking sınavının tamamını yapmayı öğreneceksin: para biriktirmeyle ilgili soruları iki üç cümleyle cevaplayacak, bir pazarı ya da sokağı dinleyenin gözünde canlanacak şekilde iki dakika anlatacak ve kamusal alanları bir görüş, bir neden ve bir örnekle tartışacaksın.","fa":"در این درس یاد می‌گیری کل آزمون Speaking را انجام بدهی: به سؤال‌های مربوط به پس‌انداز با دو سه جمله جواب بدهی، دو دقیقه یک بازار یا خیابان را طوری توصیف کنی که شنونده تصورش کند و درباره‌ی فضاهای عمومی با یک نظر، یک دلیل و یک مثال بحث کنی."},"sessions":[["explain"],["sets"],["exit"]],"explain":{"title":{"en":"Speaking: Parts 1, 2 and 3","tr":"Speaking: Part 1, 2 ve 3","fa":"Speaking: بخش‌های ۱، ۲ و ۳"},"objective":{"en":"In this lesson you will learn to take the whole Speaking test: answer questions about saving money in two or three sentences, describe a market or street for two minutes so that the listener can picture it, and discuss public spaces with a view, a reason and an example.","tr":"Bu derste Speaking sınavının tamamını yapmayı öğreneceksin: para biriktirmeyle ilgili soruları iki üç cümleyle cevaplayacak, bir pazarı ya da sokağı dinleyenin gözünde canlanacak şekilde iki dakika anlatacak ve kamusal alanları bir görüş, bir neden ve bir örnekle tartışacaksın.","fa":"در این درس یاد می‌گیری کل آزمون Speaking را انجام بدهی: به سؤال‌های مربوط به پس‌انداز با دو سه جمله جواب بدهی، دو دقیقه یک بازار یا خیابان را طوری توصیف کنی که شنونده تصورش کند و درباره‌ی فضاهای عمومی با یک نظر، یک دلیل و یک مثال بحث کنی."},"stats":[{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"11-14 min","tr":"11-14 dk","fa":"۱۱ تا ۱۴ دقیقه"}},{"label":{"en":"Parts","tr":"Kısım","fa":"بخش"},"value":"3"},{"label":{"en":"Part 2 talk","tr":"Part 2 konuşması","fa":"صحبت Part 2"},"value":{"en":"2 min","tr":"2 dk","fa":"۲ دقیقه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: money, a market, city spaces","tr":"Bu sınav: para, bir pazar, kent alanları","fa":"این آزمون: پول، یک بازار، فضاهای شهری"},"intro":{"en":"The three parts are linked: Part 1 is about you, Part 2 is one place on a card, and Part 3 widens the Part 2 topic to cities and society. Place cards need description: what you see, hear and do there.","tr":"Üç kısım birbirine bağlıdır: Part 1 seninle ilgili, Part 2 karttaki bir yer ve Part 3, Part 2 konusunu kentlere ve topluma genişletir. Yer kartları betimleme ister: orada ne gördüğün, ne duyduğun ve ne yaptığın.","fa":"سه بخش به هم وصل‌اند: Part 1 درباره‌ی خودت است، Part 2 یک مکان روی کارت و Part 3 موضوع Part 2 را به شهرها و جامعه گسترش می‌دهد. کارت‌های مکان توصیف می‌خواهند: آن‌جا چه می‌بینی، چه می‌شنوی و چه می‌کنی."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x03-s1-ctx","exam":true,"patterns":["S1-frame","S1-money"],"often":{"pattern":"S1-money","n":6,"of":40,"label":{"en":"Comes up often in the real exam: 6 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 6’sında","fa":"در آزمون واقعی زیاد می‌آید: در ۶ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 1: you, then saving money","tr":"Part 1: sen, sonra para biriktirmek","fa":"Part 1: خودت، بعد پس‌انداز"},"asks":{"en":"The examiner checks your name and asks about your work, studies or home, then four questions on one everyday topic. Here the topic is saving money.","tr":"Sınav görevlisi adını kontrol eder, işini, okulunu ya da evini sorar, sonra günlük bir konuda dört soru sorar. Burada konu para biriktirmek.","fa":"ممتحن اسمت را چک می‌کند، درباره‌ی کار، درس یا خانه‌ات می‌پرسد و بعد چهار سؤال درباره‌ی یک موضوع روزمره. این‌جا موضوع پس‌انداز است."},"fields":["Work or studies","Home","Saving habits","Childhood","Spending","Advice"],"words":[{"a":"save up for","b":"put money aside to buy something","tr":"... için para biriktirmek","fa":"برای ... پول جمع کردن"},{"a":"a budget","b":"a plan for how much to spend","tr":"bütçe","fa":"بودجه"},{"a":"pocket money","b":"money parents give children","tr":"harçlık","fa":"پول توجیبی"},{"a":"a piggy bank","b":"a box for coins","tr":"kumbara","fa":"قلک"},{"a":"impulse buy","b":"something bought without planning","tr":"anlık alışveriş","fa":"خرید هیجانی"},{"a":"tight","b":"when money is short","tr":"kısıtlı","fa":"تنگ (از نظر پول)"},{"a":"a bargain","b":"something cheap for its value","tr":"kelepir","fa":"جنس ارزان و خوب"},{"a":"cut back on","b":"spend less on","tr":"... kısmak","fa":"کم کردن خرجِ"},{"a":"treat myself","b":"buy something nice for myself","tr":"kendimi ödüllendirmek","fa":"به خودم جایزه دادن"},{"a":"it adds up","b":"small amounts become a lot","tr":"birikir","fa":"کم‌کم زیاد می‌شود"}],"traps":[{"en":"One-word answers: \"Sometimes.\" Add when, why or an example: what do you save for?","tr":"Tek kelimelik cevaplar: \"Sometimes.\" Ne zaman, neden ya da bir örnek ekle: ne için para biriktiriyorsun?","fa":"جواب‌های یک‌کلمه‌ای: «Sometimes.». بگو کی، چرا یا یک مثال: برای چه پس‌انداز می‌کنی؟"},{"en":"Wrong tense for childhood questions. \"Did you save money as a child?\" needs the past simple or \"used to\".","tr":"Çocukluk sorularında yanlış zaman. \"Çocukken para biriktirir miydin?\" past simple ya da \"used to\" ister.","fa":"زمان غلط برای سؤال‌های کودکی. «بچه که بودی پس‌انداز می‌کردی؟» گذشته‌ی ساده یا «used to» می‌خواهد."}],"example":{"text":"Q: \"Do you find it easy to save money?\"","item":"Which answer is the right length?","answer":"Not really. I try to put a little aside every month, but it usually goes on train tickets and eating out.","why":{"en":"An answer, then what you do and why it is hard: about ten seconds.","tr":"Bir cevap, sonra ne yaptığın ve neden zor olduğu: yaklaşık on saniye.","fa":"یک جواب، بعد کاری که می‌کنی و چرا سخت است: حدود ده ثانیه."}}},{"id":"x03-s2-ctx","exam":true,"patterns":["S2-place","PARA-discuss"],"often":{"pattern":"S2-place","n":7,"of":40,"label":{"en":"Comes up often in the real exam: 7 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 2: a market or street you enjoy visiting","tr":"Part 2: gezmekten hoşlandığın bir pazar ya da sokak","fa":"Part 2: بازار یا خیابانی که دوست داری به آن سر بزنی"},"asks":{"en":"You get a card about a place: a market or a street you enjoy visiting. One minute to prepare, then up to two minutes alone. Describe it so the examiner can picture it, then explain why you like it.","tr":"Bir yer kartı alırsın: gezmekten hoşlandığın bir pazar ya da sokak. Bir dakika hazırlık, sonra iki dakikaya kadar tek başına konuşma. Sınav görevlisinin gözünde canlanacak şekilde anlat, sonra neden sevdiğini açıkla.","fa":"کارتی درباره‌ی یک مکان می‌گیری: بازار یا خیابانی که دوست داری بروی. یک دقیقه آماده شدن، بعد تا دو دقیقه حرف زدن به‌تنهایی. طوری توصیفش کن که ممتحن بتواند تصورش کند و بعد بگو چرا دوستش داری."},"fields":["Where it is","What you can see and buy","What you do there","Why you enjoy it"],"words":[{"a":"it’s tucked away","b":"it’s hidden, not easy to find","tr":"gözden uzak bir yerde","fa":"جایی دنج و پنهان"},{"a":"stalls","b":"small tables or stands that sell things","tr":"tezgâhlar","fa":"غرفه‌ها"},{"a":"bustling","b":"busy and full of life","tr":"cıvıl cıvıl","fa":"پرجنب‌وجوش"},{"a":"the smell of","b":"you can smell... as you walk in","tr":"... kokusu","fa":"بوی ..."},{"a":"locals","b":"people who live there","tr":"yerliler","fa":"اهالی محل"},{"a":"haggle","b":"argue about the price","tr":"pazarlık etmek","fa":"چانه زدن"},{"a":"browse","b":"look around without needing to buy","tr":"göz gezdirmek","fa":"گشت زدن و نگاه کردن"},{"a":"a regular","b":"someone who goes often","tr":"müdavim","fa":"مشتری ثابت"},{"a":"it reminds me of","b":"it makes me think of","tr":"bana ... hatırlatıyor","fa":"مرا یاد ... می‌اندازد"},{"a":"a real atmosphere","b":"a special feeling","tr":"gerçek bir hava","fa":"حال‌وهوای واقعی"}],"traps":[{"en":"A list of things you can buy. Describe with the senses (sounds, smells, colours) and tell one small story.","tr":"Satın alınabilecek şeylerin listesi. Duyularla anlat (sesler, kokular, renkler) ve küçük bir hikâye anlat.","fa":"فهرست چیزهایی که می‌شود خرید. با حواس توصیف کن (صدا، بو، رنگ) و یک داستان کوچک تعریف کن."},{"en":"Stopping before \"explain why you enjoy it\". That line is where you give reasons and feelings to fill the second minute.","tr":"\"Explain why you enjoy it\" satırına gelmeden durmak. O satır, ikinci dakikayı doldurmak için nedenler ve duygular verdiğin yerdir.","fa":"ساکت شدن قبل از «explain why you enjoy it». این خط جایی است که با دلیل و احساس دقیقه‌ی دوم را پر می‌کنی."}],"example":{"text":"Card line: \"what you can see and buy there\"","item":"Which sentence describes the place best?","answer":"The street is lined with tiny stalls selling spices, and you can smell cinnamon long before you see it.","why":{"en":"A picture (tiny stalls), a detail (spices) and a sense (smell).","tr":"Bir görüntü (küçük tezgâhlar), bir ayrıntı (baharatlar) ve bir duyu (koku).","fa":"یک تصویر (غرفه‌های کوچک)، یک جزئیات (ادویه‌ها) و یک حس (بو)."}}},{"id":"x03-s3-ctx","exam":true,"patterns":["S3-culture","PARA-discuss","TR-short"],"often":{"pattern":"S3-culture","n":6,"of":40,"label":{"en":"Comes up often in the real exam: 6 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 6’sında","fa":"در آزمون واقعی زیاد می‌آید: در ۶ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 3: public spaces and green areas","tr":"Part 3: kamusal alanlar ve yeşil alanlar","fa":"Part 3: فضاهای عمومی و فضای سبز"},"asks":{"en":"The examiner asks six general questions linked to the Part 2 topic: why people use markets and public spaces, and how green areas in cities should be planned and paid for.","tr":"Sınav görevlisi Part 2 konusuyla bağlantılı altı genel soru sorar: insanlar pazarları ve kamusal alanları neden kullanır, kentlerdeki yeşil alanlar nasıl planlanmalı ve nasıl finanse edilmeli.","fa":"ممتحن شش سؤال کلی مرتبط با موضوع Part 2 می‌پرسد: چرا مردم از بازارها و فضاهای عمومی استفاده می‌کنند و فضای سبز شهری چطور باید برنامه‌ریزی و تأمین مالی شود."},"fields":["Markets and shopping centres","Meeting places","Young and old","Parks","Who pays","The future"],"words":[{"a":"public space","b":"a place open to everyone","tr":"kamusal alan","fa":"فضای عمومی"},{"a":"a sense of community","b":"feeling part of a group of neighbours","tr":"topluluk duygusu","fa":"حس همبستگی محلی"},{"a":"green space","b":"parks, gardens and trees","tr":"yeşil alan","fa":"فضای سبز"},{"a":"well maintained","b":"kept clean and in good condition","tr":"bakımlı","fa":"خوب نگهداری‌شده"},{"a":"local authorities","b":"the council / the city government","tr":"yerel yönetimler","fa":"مقامات محلی"},{"a":"fund","b":"pay for","tr":"finanse etmek","fa":"تأمین مالی کردن"},{"a":"urban","b":"in a city","tr":"kentsel","fa":"شهری"},{"a":"mental health","b":"how people feel inside","tr":"ruh sağlığı","fa":"سلامت روان"},{"a":"it depends on","b":"it varies with","tr":"... bağlıdır","fa":"بستگی دارد به"},{"a":"in the long term","b":"over many years","tr":"uzun vadede","fa":"در درازمدت"}],"traps":[{"en":"A one-sentence opinion. Part 3 wants a view, a reason, an example and, when it helps, the other side.","tr":"Tek cümlelik bir görüş. Part 3 bir görüş, bir neden, bir örnek ve gerektiğinde karşı tarafı ister.","fa":"نظری در یک جمله. Part 3 یک نظر، یک دلیل، یک مثال و هرجا لازم بود طرف مقابل را می‌خواهد."},{"en":"Only talking about your own park. \"Why do cities need green spaces?\" is about cities and people in general.","tr":"Yalnızca kendi parkından söz etmek. \"Kentlerin neden yeşil alanlara ihtiyacı var?\" sorusu genel olarak kentler ve insanlarla ilgilidir.","fa":"فقط درباره‌ی پارک خودت حرف زدن. «چرا شهرها به فضای سبز نیاز دارند؟» درباره‌ی شهرها و آدم‌ها به‌طور کلی است."}],"example":{"text":"Q: \"Why do some people prefer markets to supermarkets?\"","item":"Which answer has a view, a reason and an example?","answer":"I think many people enjoy the personal contact. At a market you can talk to the person who grew the food, for example, which never happens in a supermarket.","why":{"en":"View (I think...), reason (personal contact), example (talking to the grower).","tr":"Görüş (I think...), neden (yüz yüze iletişim), örnek (üreticiyle konuşmak).","fa":"نظر (I think...)، دلیل (ارتباط شخصی)، مثال (حرف زدن با کسی که محصول را کاشته)."}}},{"id":"S2-place","ctx":["S2-place"],"title":{"en":"A place","tr":"Bir yer","fa":"یک مکان"},"asks":{"en":"A card about a place: a garden or park, a place with a view, an attraction, the neighbourhood where you grew up, a city to visit, a hotel. The prompts ask where it is, what it is like, what you do there, and why it matters.","tr":"Bir yer hakkında kart: bir bahçe ya da park, manzaralı bir yer, bir turistik yer, büyüdüğün mahalle, gezilecek bir şehir, bir otel. Maddeler nerede olduğunu, neye benzediğini, orada ne yaptığını ve neden önemli olduğunu sorar.","fa":"کارتی درباره‌ی یک مکان: یک باغ یا پارک، جایی با منظره، یک جاذبه‌ی گردشگری، محله‌ای که در آن بزرگ شدی، شهری برای دیدن، یک هتل. بندها می‌پرسند کجاست، چه شکلی است، آنجا چه می‌کنی و چرا برایت مهم است."},"fields":["Describe a park or garden you like.","Describe a place with a beautiful view.","Describe a tourist attraction you would recommend.","Describe the neighbourhood where you grew up.","Describe a city you would like to visit."],"words":[{"a":"nice","b":"peaceful / charming / breathtaking","tr":"huzurlu, büyüleyici","fa":"آرام، دلنشین، نفس‌گیر"},{"a":"big","b":"huge / spacious","tr":"geniş","fa":"بزرگ و جادار"},{"a":"old","b":"historic / centuries old","tr":"tarihî","fa":"تاریخی"},{"a":"it is near","b":"it's a short walk from","tr":"... -e çok yakın","fa":"چند قدمی ... است"},{"a":"trees around it","b":"surrounded by trees","tr":"ağaçlarla çevrili","fa":"دورتادور درخت"},{"a":"you can see far","b":"it looks out over the whole valley","tr":"bütün vadiye bakıyor","fa":"رو به کل دره است"},{"a":"many tourists","b":"packed with tourists","tr":"turist kaynıyor","fa":"پر از توریست"},{"a":"I go there","b":"I tend to go there when","tr":"genelde ... oraya giderim","fa":"معمولاً وقتی ... آنجا می‌روم"},{"a":"I feel good there","b":"it makes me feel calm","tr":"bana huzur veriyor","fa":"آرامم می‌کند"},{"a":"I remember","b":"what sticks in my mind is","tr":"aklımda kalan","fa":"چیزی که در ذهنم مانده"},{"a":"you should go","b":"it's well worth a visit","tr":"kesinlikle görülmeye değer","fa":"واقعاً ارزش دیدن دارد"},{"a":"small details","b":"the smell of the pine trees","tr":"çam ağaçlarının kokusu","fa":"بوی درخت‌های کاج"}],"traps":[{"en":"Describing only what it looks like: use every prompt, and keep time for the \"explain\" line.","tr":"Yalnızca neye benzediğini anlatmak: her maddeyi kullan ve \"explain\" satırına zaman bırak.","fa":"فقط توصیف ظاهر: از همه‌ی بندها استفاده کن و برای خط «explain» وقت نگه دار."},{"en":"Present tenses for what it is like; past tenses for a visit you remember.","tr":"Neye benzediği için şimdiki zaman; hatırladığın bir ziyaret için geçmiş zaman.","fa":"برای اینکه چطور جایی است زمان حال؛ برای بازدیدی که یادت مانده زمان گذشته."}],"example":{"lines":[["Candidate","I’d like to talk about a hill just outside my hometown, about twenty minutes from my house by bike."],["Candidate","From the top you can see the whole valley, with the river shining in the middle."],["Candidate","What sticks in my mind is the first time I watched the sunrise there with my brother."]],"item":"Which prompts has the speaker covered so far?","answer":"Where it is, what you can see, and a memory that leads into why it matters.","why":{"en":"Three lines cover three prompts, and the memory prepares the \"explain\" line.","tr":"Üç satır üç maddeyi karşılıyor; anı da \"explain\" satırını hazırlıyor.","fa":"سه خط سه بند را پوشش می‌دهند و آن خاطره خط «explain» را آماده می‌کند."}},"ideas":["one thing you can see, hear or smell there","a short story of one visit","who you go with","how it has changed","why it matters to you (the \"explain\" line)"],"general":true,"patterns":["S2-place"],"often":{"pattern":"S2-place","n":7,"of":40,"label":{"en":"Comes up often in the real exam: 7 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ آزمون از ۴۰ آزمونِ اخیر"}}},{"id":"S3-culture","ctx":["S3-culture"],"title":{"en":"Culture and the built environment","tr":"Kültür ve yapılı çevre","fa":"فرهنگ و محیط ساخته‌شده"},"asks":{"en":"General questions linked to the Part 2 card, about theatre and cinema, statues and old buildings, science and research, and homes of the future. The examiner wants an opinion, a reason, an example and, when it helps, the other side.","tr":"Part 2 kartına bağlı, tiyatro ve sinema, heykeller ve eski binalar, bilim ve araştırma, geleceğin evleri hakkında genel sorular. Sınav görevlisi bir görüş, bir neden, bir örnek ve gerektiğinde karşı tarafı ister.","fa":"سؤال‌های کلی مرتبط با کارت Part 2، درباره‌ی تئاتر و سینما، مجسمه‌ها و ساختمان‌های قدیمی، علم و پژوهش، و خانه‌های آینده. ممتحن یک نظر، یک دلیل، یک مثال و هرجا لازم بود طرف مقابل را می‌خواهد."},"fields":["Why is it important to protect old buildings?","Is the cinema still popular?","Should cities have more statues and public art?","How will homes change in the future?","Should governments pay for scientific research?"],"words":[{"a":"old buildings","b":"historic buildings / heritage sites","tr":"tarihî binalar","fa":"بناهای تاریخی"},{"a":"keep","b":"preserve / restore","tr":"korumak, restore etmek","fa":"حفظ کردن، مرمت کردن"},{"a":"modern","b":"contemporary","tr":"çağdaş","fa":"معاصر"},{"a":"ugly","b":"an eyesore","tr":"göz zevkini bozan","fa":"زشت و ناخوشایند"},{"a":"city look","b":"the skyline / architecture","tr":"şehrin silueti, mimari","fa":"منظره‌ی شهر، معماری"},{"a":"public art","b":"statues and murals","tr":"kamusal sanat","fa":"هنر عمومی"},{"a":"identity","b":"a sense of history","tr":"kimlik, tarih bilinci","fa":"هویت، حس تاریخ"},{"a":"plays","b":"live theatre / performances","tr":"tiyatro oyunları","fa":"اجرای زنده"},{"a":"watch at home","b":"stream films","tr":"evde izlemek","fa":"آنلاین تماشا کردن"},{"a":"research","b":"scientific studies","tr":"bilimsel çalışmalar","fa":"پژوهش علمی"},{"a":"paid by the state","b":"publicly funded","tr":"kamu tarafından finanse edilen","fa":"با بودجه‌ی دولتی"},{"a":"in future","b":"in the coming decades","tr":"önümüzdeki on yıllarda","fa":"در دهه‌های آینده"}],"traps":[{"en":"Abstract questions need a concrete example: name a building, a film or a discovery.","tr":"Soyut sorular somut bir örnek ister: bir bina, bir film ya da bir buluşun adını ver.","fa":"سؤال‌های انتزاعی مثال مشخص می‌خواهند: اسم یک ساختمان، فیلم یا کشف را بیاور."},{"en":"If you do not know much about the topic, say what you think and why. There is no wrong opinion.","tr":"Konuyu çok bilmiyorsan ne düşündüğünü ve nedenini söyle. Yanlış görüş diye bir şey yok.","fa":"اگر درباره‌ی موضوع زیاد نمی‌دانی، بگو چه فکر می‌کنی و چرا. نظر غلط وجود ندارد."}],"example":{"lines":[["Examiner","Why is it important to protect old buildings?"],["Candidate","Mainly because they show where a city has come from."],["Candidate","In my hometown, the old market hall reminds everyone of the time when the town was a trading centre."],["Candidate","Having said that, I don’t think every old building should be kept, if it is unsafe or empty."]],"item":"Which moves does the answer make?","answer":"Opinion with a reason, a named example, then a limit (\"Having said that...\").","why":{"en":"A named example turns an abstract idea into something the examiner can picture.","tr":"Adı verilen bir örnek soyut bir fikri sınav görevlisinin gözünde canlandırabileceği bir şeye çevirir.","fa":"مثال نام‌دار یک ایده‌ی انتزاعی را به چیزی تبدیل می‌کند که ممتحن بتواند تصورش کند."}},"ideas":["old buildings give a city its identity","restoration is expensive; new buildings are efficient","live theatre offers something screens cannot","public money for research benefits everyone"],"general":true,"patterns":["S3-culture"],"often":{"pattern":"S3-culture","n":6,"of":40,"label":{"en":"Comes up often in the real exam: 6 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 6’sında","fa":"در آزمون واقعی زیاد می‌آید: در ۶ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Three parts, one examiner","tr":"Üç kısım, bir sınav görevlisi","fa":"سه بخش، یک ممتحن"},"body":{"en":"Part 1 (4-5 minutes): questions about you and one everyday topic. Part 2 (3-4 minutes): one minute to prepare, then up to two minutes alone, then one short question. Part 3 (4-5 minutes): a discussion of general questions. The test is recorded.","tr":"Part 1 (4-5 dakika): seninle ve günlük bir konuyla ilgili sorular. Part 2 (3-4 dakika): bir dakika hazırlık, sonra iki dakikaya kadar tek başına konuşma, sonra kısa bir soru. Part 3 (4-5 dakika): genel soruların tartışması. Sınav kaydedilir.","fa":"Part 1 (۴ تا ۵ دقیقه): سؤال‌هایی درباره‌ی خودت و یک موضوع روزمره. Part 2 (۳ تا ۴ دقیقه): یک دقیقه آماده شدن، بعد تا دو دقیقه حرف زدن به‌تنهایی و بعد یک سؤال کوتاه. Part 3 (۴ تا ۵ دقیقه): بحث درباره‌ی سؤال‌های کلی. آزمون ضبط می‌شود."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Describe a place with the senses","tr":"Bir yeri duyularla anlat","fa":"یک مکان را با حواس توصیف کن"},"steps":[{"en":"Part 1: answer, then add one reason or example. Use the past for childhood questions.","tr":"Part 1: cevap ver, sonra bir neden ya da örnek ekle. Çocukluk soruları için geçmiş zaman kullan.","fa":"Part 1: جواب بده و بعد یک دلیل یا مثال اضافه کن. برای سؤال‌های کودکی از گذشته استفاده کن."},{"en":"Part 2: plan four notes: where, what you see and hear, what you do, why you like it. Add one small story.","tr":"Part 2: dört not planla: nerede, ne görüp duyuyorsun, ne yapıyorsun, neden seviyorsun. Küçük bir hikâye ekle.","fa":"Part 2: چهار یادداشت برنامه بریز: کجا، چه می‌بینی و می‌شنوی، چه کار می‌کنی، چرا دوستش داری. یک داستان کوچک هم اضافه کن."},{"en":"Part 3: give a view, a reason and an example, then the other side if it helps.","tr":"Part 3: bir görüş, bir neden ve bir örnek ver; gerekiyorsa karşı tarafı da söyle.","fa":"Part 3: یک نظر، یک دلیل و یک مثال بده و اگر کمک می‌کند طرف مقابل را هم بگو."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"A list is not a description","tr":"Liste betimleme değildir","fa":"فهرست، توصیف نیست"},"body":{"en":"In Part 2, a list of things (\"fruit, clothes, shoes...\") runs out after thirty seconds. Describe one or two things in detail instead, say how the place feels, and keep your reasons for the last part of the card.","tr":"Part 2’de eşya listesi (\"meyve, giysi, ayakkabı...\") otuz saniyede tükenir. Bunun yerine bir iki şeyi ayrıntılı anlat, yerin nasıl hissettirdiğini söyle ve nedenlerini kartın son bölümüne sakla.","fa":"در Part 2، فهرست چیزها («میوه، لباس، کفش...») بعد از سی ثانیه تمام می‌شود. به جایش یکی دو چیز را با جزئیات توصیف کن، بگو آن‌جا چه حسی دارد و دلیل‌هایت را برای بخش آخر کارت نگه دار."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Planning a place talk in one minute","tr":"Bir dakikada bir yer konuşması planlamak","fa":"برنامه‌ریزی صحبت درباره‌ی یک مکان در یک دقیقه"},"instruction":"Card: Describe a café you like to visit. You should say: where it is; what it looks like; what you do there; and explain why you like it.","item":"Write one key word for each line.","answer":"old station · plants + big windows · read, meet Ana · quiet, owner knows me","walk":[{"en":"Choose details you can see: plants, big windows.","tr":"Görebileceğin ayrıntıları seç: bitkiler, büyük pencereler.","fa":"جزئیاتی را انتخاب کن که دیده می‌شوند: گیاه‌ها، پنجره‌های بزرگ."},{"en":"Add a person or a habit: meeting a friend, reading.","tr":"Bir kişi ya da bir alışkanlık ekle: bir arkadaşla buluşmak, kitap okumak.","fa":"یک آدم یا یک عادت اضافه کن: دیدن یک دوست، کتاب خواندن."},{"en":"Save two reasons for the explain line: quiet, the owner knows me.","tr":"Açıklama satırı için iki neden sakla: sakin, sahibi beni tanıyor.","fa":"دو دلیل برای خط توضیح نگه دار: آرام است، صاحبش مرا می‌شناسد."}]},"quick":{"prompt":"Part 3: \"Why do cities need parks?\" Which answer is about people in general?","options":["I go to the park on Sundays.","Yes, they do.","Parks give people in crowded areas a place to relax, which is good for their mental health."],"correct":2,"why":{"en":"It speaks about people in cities and gives a reason; the others are about the speaker only or too short.","tr":"Kentlerdeki insanlardan söz ediyor ve bir neden veriyor; diğerleri yalnızca konuşanla ilgili ya da çok kısa.","fa":"درباره‌ی آدم‌های شهر حرف می‌زند و دلیل می‌آورد؛ بقیه فقط درباره‌ی گوینده‌اند یا خیلی کوتاه‌اند."}},"remember":{"en":"Part 1: answer plus a detail. Part 2: describe with the senses, then explain. Part 3: view, reason, example.","tr":"Part 1: cevap artı bir ayrıntı. Part 2: duyularla betimle, sonra açıkla. Part 3: görüş, neden, örnek.","fa":"Part 1: جواب به‌اضافه‌ی یک جزئیات. Part 2: با حواس توصیف کن و بعد توضیح بده. Part 3: نظر، دلیل، مثال."},"type":"explain","id":"c-x03-s-e","course":"ielts-exams","exam":"exam-03","unit":"x03-s"},"sets":{"title":{"en":"The Speaking test","tr":"Speaking sınavı","fa":"آزمون Speaking"},"note":{"en":"Do the three parts in order, without a break, as in the real test. Record yourself if you can, then use the self-check under each part.","tr":"Gerçek sınavdaki gibi üç kısmı sırayla ve ara vermeden yap. Yapabilirsen kendini kaydet, sonra her kısmın altındaki öz değerlendirmeyi kullan.","fa":"سه بخش را به ترتیب و بدون مکث انجام بده، مثل آزمون واقعی. اگر می‌توانی صدایت را ضبط کن و بعد از خودارزیابیِ زیر هر بخش استفاده کن."},"sequential":true,"examinerVoice":{"accent":"British (standard Southern)","gender":"F","tts":{"engine":"kokoro","voice":"bf_alice"},"role":"Examiner"},"sets":[{"part":"Part 1","ctx":["S1-frame","S1-money"],"minutes":[4,5],"title":{"en":"Part 1: about you, then saving money","tr":"Part 1: senin hakkında, sonra para biriktirmek","fa":"Part 1: درباره‌ی خودت، بعد پس‌انداز"},"examinerIntro":["Good morning. My name is Claire Dunmore. Can you tell me your full name, please?","Thank you. And can I see your identification, please?","Thank you. Now, in this first part, I’d like to ask you some questions about yourself."],"frame":["Do you work or are you a student?","What is the most difficult part of your work or your studies?","Let’s talk about where you live. What do you like about your home?"],"topicIntro":"Now let’s talk about saving money.","questions":["Do you find it easy to save money? [Why/Why not?]","Did you save money when you were a child?","What do you usually save money for?","Do you think it is better to save money or to spend it and enjoy it now?"],"model":"Q: Do you find it easy to save money?\nA: Not really, to be honest. I try to put a little aside at the start of every month, but it usually disappears on train tickets and eating out with friends.\n\nQ: Did you save money when you were a child?\nA: Yes, I had a little tin on my shelf, and I used to put my pocket money in it every Saturday. I once saved for nearly a year to buy a bike.\n\nQ: What do you usually save money for?\nA: Mostly for travel. I’d rather go somewhere new once a year than buy lots of small things that I don’t really need.\n\nQ: Is it better to save money or to spend it now?\nA: I think you need a balance. It’s sensible to keep some savings for emergencies, but if you never spend anything on yourself, life gets a bit grey.","moves":[{"label":{"en":"Answer first","tr":"Önce cevap","fa":"اول جواب"},"example":"Not really, to be honest."},{"label":{"en":"Add a reason or an example","tr":"Bir neden ya da örnek ekle","fa":"یک دلیل یا مثال اضافه کن"},"example":"It usually disappears on train tickets and eating out with friends."},{"label":{"en":"Use the right time: past for childhood","tr":"Doğru zamanı kullan: çocukluk için geçmiş","fa":"زمان درست را به کار ببر: گذشته برای کودکی"},"example":"I used to put my pocket money in it every Saturday."}],"selfCheck":[{"en":"I answered every question with two or three sentences, not one word.","tr":"Her soruyu tek kelimeyle değil, iki üç cümleyle cevapladım.","fa":"به هر سؤال با دو سه جمله جواب دادم، نه یک کلمه."},{"en":"I added a reason or an example after each answer.","tr":"Her cevaptan sonra bir neden ya da örnek ekledim.","fa":"بعد از هر جواب یک دلیل یا مثال اضافه کردم."},{"en":"I used the past simple or \"used to\" for my childhood.","tr":"Çocukluğum için past simple ya da \"used to\" kullandım.","fa":"برای کودکی‌ام از گذشته‌ی ساده یا «used to» استفاده کردم."}]},{"part":"Part 2","ctx":["S2-place"],"minutes":[3,4],"title":{"en":"Part 2: a market or street you enjoy visiting","tr":"Part 2: gezmekten hoşlandığın bir pazar ya da sokak","fa":"Part 2: بازار یا خیابانی که دوست داری به آن سر بزنی"},"examinerIntro":["Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. Before you talk, you’ll have one minute to think about what you’re going to say. You can make some notes if you wish. Do you understand?","Here’s some paper and a pencil for making notes, and here’s your topic. I’d like you to describe a market or a street that you enjoy visiting.","All right? Remember you have one to two minutes for this. Don’t worry if I stop you. I’ll tell you when the time is up. Can you start speaking now, please?"],"card":{"task":"Describe a market or a street that you enjoy visiting.","bullets":["where it is","what you can see and buy there","what you usually do there","and explain why you enjoy visiting it"]},"prep":60,"talk":120,"roundingOff":["Do you prefer shopping in markets or in large shopping centres?"],"model":"I’d like to describe a small covered market in the old part of my city. It’s tucked away behind the main square, so a lot of visitors walk straight past it, but for local people it’s a real institution. It’s been there for more than a hundred years, and it still has its original iron roof.\n\nInside, it’s bustling, especially on Saturday mornings. There are about forty stalls, and most of them sell fresh food: piles of oranges and tomatoes, cheese from the mountain villages, and fish laid out on ice. At the far end there’s an old man who sells nothing but honey, and you can taste every kind before you choose. The smell of fresh bread and coffee hits you as soon as you walk in.\n\nI usually go there with my mother. We buy our vegetables for the week, and then we always finish at a tiny café in the corner, where we sit on high stools and watch everyone rushing around. The stallholders know us by now, so there’s always a bit of chat, and sometimes the fruit seller gives us an extra handful of cherries.\n\nWhy do I enjoy it so much? Partly because the food really is better than in the supermarket, and often cheaper too. But mainly it’s the atmosphere. In a supermarket nobody speaks to you, whereas at the market you feel part of a small community. It reminds me of going there with my grandmother when I was a child, so it has a lot of memories for me as well.","moves":[{"label":{"en":"Start with where it is","tr":"Nerede olduğuyla başla","fa":"با جایش شروع کن"},"example":"I’d like to describe a small covered market in the old part of my city. It’s tucked away behind the main square..."},{"label":{"en":"Describe with the senses and one story","tr":"Duyularla ve bir hikâyeyle betimle","fa":"با حواس و یک داستان توصیف کن"},"example":"The smell of fresh bread and coffee hits you as soon as you walk in... sometimes the fruit seller gives us an extra handful of cherries."},{"label":{"en":"Spend time on the explain line","tr":"Açıklama satırına zaman ayır","fa":"روی خط توضیح وقت بگذار"},"example":"Partly because the food really is better... But mainly it’s the atmosphere."}],"selfCheck":[{"en":"I covered all four lines of the card and spoke for close to two minutes.","tr":"Kartın dört satırının hepsini ele aldım ve iki dakikaya yakın konuştum.","fa":"هر چهار خط کارت را گفتم و نزدیک دو دقیقه حرف زدم."},{"en":"I described the place with sights, sounds or smells, not just a list.","tr":"Yeri yalnızca bir listeyle değil, görüntüler, sesler ya da kokularla anlattım.","fa":"مکان را با تصویر، صدا یا بو توصیف کردم، نه فقط با یک فهرست."},{"en":"I gave at least two reasons in the explain part.","tr":"Açıklama bölümünde en az iki neden verdim.","fa":"در بخش توضیح دست‌کم دو دلیل آوردم."}]},{"part":"Part 3","ctx":["S3-culture"],"minutes":[4,5],"title":{"en":"Part 3: public spaces and green areas","tr":"Part 3: kamusal alanlar ve yeşil alanlar","fa":"Part 3: فضاهای عمومی و فضای سبز"},"examinerIntro":["We’ve been talking about a market or street you enjoy, and I’d like to discuss with you one or two more general questions related to this."],"subtopics":[{"title":"Markets and meeting places","questions":["Why do some people prefer small markets to large shopping centres?","How important is it for a town to have places where people can meet for free?","Do young people and older people use public spaces in different ways?"]},{"title":"Green areas in cities","questions":["Why do cities need parks and green spaces?","Who should pay for keeping parks clean and safe: the city or the people who use them?","How do you think public spaces in cities will change in the future?"]}],"model":"Q: Why do cities need parks and green spaces?\nA: I think the main reason is health, both physical and mental. In crowded cities many people live in small flats without gardens, so a park is the only place where they can walk, play sport or simply sit under a tree. Several studies have linked green spaces with lower stress. On top of that, trees cool the streets in summer, which is becoming more important as cities get hotter.\n\nQ: Who should pay for keeping parks clean and safe?\nA: Mainly the city, in my view, because parks are meant to be open to everyone, including people who could never afford to pay. If you charged for entry, you would shut out exactly the people who need them most. That said, I think local businesses could contribute, for example by sponsoring a playground, and volunteers can help with things like planting.","moves":[{"label":{"en":"Give a clear view","tr":"Net bir görüş ver","fa":"نظرت را روشن بگو"},"example":"Mainly the city, in my view, because parks are meant to be open to everyone."},{"label":{"en":"Support it: reason + example","tr":"Destekle: neden + örnek","fa":"پشتیبانی کن: دلیل + مثال"},"example":"If you charged for entry, you would shut out exactly the people who need them most."},{"label":{"en":"Show the other side","tr":"Karşı tarafı göster","fa":"طرف مقابل را نشان بده"},"example":"That said, I think local businesses could contribute, for example by sponsoring a playground..."}],"selfCheck":[{"en":"I gave a clear view in my first sentence.","tr":"İlk cümlemde net bir görüş verdim.","fa":"در جمله‌ی اولم نظر روشنی دادم."},{"en":"I supported it with a reason and an example.","tr":"Onu bir neden ve bir örnekle destekledim.","fa":"آن را با یک دلیل و یک مثال پشتیبانی کردم."},{"en":"I talked about cities and people in general, not only about my own town.","tr":"Yalnızca kendi şehrimden değil, genel olarak kentlerden ve insanlardan söz ettim.","fa":"درباره‌ی شهرها و آدم‌ها به‌طور کلی حرف زدم، نه فقط شهر خودم."}]}],"type":"sets","id":"c-x03-s-p","course":"ielts-exams","exam":"exam-03","unit":"x03-s"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"I’m saving up for a new laptop.\" This means you are...","options":["paying for it in parts","putting money aside to buy one","borrowing money for it"],"correct":1,"why":{"en":"Save up for = keep money until you have enough to buy something.","tr":"Save up for = bir şeyi alacak kadar olana dek para biriktirmek.","fa":"save up for یعنی پول کنار گذاشتن تا برای خریدن چیزی کافی شود."}},{"tests":"paraphrase","point":2,"prompt":"Which phrase describes a place that is busy and full of life?","options":["It’s bustling.","It’s deserted.","It’s run-down."],"correct":0,"why":{"en":"Bustling = busy, with a lot of people and activity.","tr":"Bustling = kalabalık, insan ve hareket dolu.","fa":"bustling یعنی شلوغ و پر از آدم و جنب‌وجوش."}},{"tests":"method","point":2,"prompt":"Your Part 2 card is about a place. After forty seconds you have said where it is and listed what it sells. What should you do next?","options":["Stop: the card is answered","List more things it sells","Describe one or two things in detail, tell a small story, then explain why you like it"],"correct":2,"why":{"en":"Details, a story and reasons fill the two minutes; a list runs out.","tr":"Ayrıntılar, bir hikâye ve nedenler iki dakikayı doldurur; liste ise tükenir.","fa":"جزئیات، یک داستان و دلیل‌ها دو دقیقه را پر می‌کنند؛ فهرست تمام می‌شود."}},{"tests":"trap","point":3,"prompt":"Part 3: \"Should cities charge people to use parks?\" Which answer has the most complete structure?","options":["No.","No, because parks should be open to everyone; charging would keep poorer families out, although businesses could help pay.","I don’t pay to go to my local park."],"correct":1,"why":{"en":"A view, a reason, a consequence and the other side; the last answer is only about the speaker.","tr":"Bir görüş, bir neden, bir sonuç ve karşı taraf; son cevap yalnızca konuşanla ilgili.","fa":"یک نظر، یک دلیل، یک پیامد و طرف مقابل؛ جواب آخر فقط درباره‌ی گوینده است."}},{"tests":"trap","point":1,"prompt":"Part 1: \"Did you save money when you were a child?\" Which answer uses the right tense?","options":["Yes, I used to keep my pocket money in a tin.","Yes, I keep my pocket money in a tin.","Yes, I have kept my pocket money in a tin."],"correct":0,"why":{"en":"A childhood habit needs \"used to\" or the past simple.","tr":"Çocukluk alışkanlığı \"used to\" ya da past simple ister.","fa":"عادتِ دوران کودکی «used to» یا گذشته‌ی ساده می‌خواهد."}}],"id":"c-x03-s-x","course":"ielts-exams","exam":"exam-03","unit":"x03-s"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
